import React, {
    useRef,
    useState,
    useEffect
} from 'react'

import {
    Text,
    Animated,
    Dimensions,
    TouchableOpacity,
    Button,
    StyleSheet
} from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles'

export function Alert() {
    const [active, setActive] = useState(false);
    const fadeAnim = useRef(new Animated.Value(0)).current;

    const {
        alertMessage,
        alertActive
    } = useContexState();

    const {
        setAlertActive,
    } = useContexState();


    function AnimatedAlert(value: boolean, message = '') {
        setActive(true);
        Animated.timing(fadeAnim, {
            toValue: value ? 1 : 0,
            duration: 700,
        } as Animated.TimingAnimationConfig).start(() => {
            if (!value) {
                setActive(false)
            };
        });
    };


    useEffect(() => {
        AnimatedAlert(alertActive, alertMessage);
    }, [alertActive]);


    return active ? <>
        <TouchableOpacity
            onPress={() => {
                setAlertActive(false)
            }}
            style={{
                position: 'absolute',
                alignItems: 'center',
                justifyContent: 'center',
                minWidth: Dimensions.get('window').width,
                minHeight: Dimensions.get('window').height
            }} />

        <Animated.View style={[styles.container, { opacity: fadeAnim }]} >
            <Text style={styles.listText}>{alertMessage}</Text>
        </Animated.View>
    </> : null
};
